#include <WiFi.h>
#include <PubSubClient.h>
WiFiClient network;
PubSubClient mqtt(network);
void command(char* topic, byte* payload, unsigned int length) {
  String text = "";
  for (unsigned int i = 0; i < length; i++) text += char(payload[i]);
  if (text == "ON" || text == "OFF") {
    digitalWrite(18, text == "ON");
    mqtt.publish("bench/lamp/state", text.c_str());
  } else mqtt.publish("bench/lamp/error", "INVALID");
}
void setup() {
  Serial.begin(115200); pinMode(18, OUTPUT);
  WiFi.begin("VoltNet", "pass");
  while (WiFi.status() != WL_CONNECTED) delay(20);
  mqtt.setServer("broker.voltquest.local", 1883); mqtt.setCallback(command);
  mqtt.connect("command-desk"); mqtt.subscribe("bench/lamp/set");
}
void loop() { mqtt.loop(); }
